// ── Valida X-Hub-Signature-256 ────────────────────────────────────────────
// Meta firma el cuerpo CRUDO con HMAC-SHA256 usando el App Secret.
// n8n bloquea el módulo 'crypto', así que va en JS puro (mismo núcleo
// SHA-256 que ya usamos en "Preparar evento Meta" para el CAPI).
//
// Se valida sobre $binary.data (los bytes tal cual llegaron), NUNCA sobre
// JSON.stringify($json.body): al reserializar, emojis y tildes cambian de
// codificación y la firma dejaría de cuadrar en mensajes reales.

// El secreto NO vive dentro del nodo: llega del entorno de n8n (fichero wa.env).
const APP_SECRET = $env.WA_APP_SECRET || '';

function sha256Bytes(input){
  function rotr(n,x){return (x>>>n)|(x<<(32-n));}
  function ch(x,y,z){return (x&y)^(~x&z);}
  function maj(x,y,z){return (x&y)^(x&z)^(y&z);}
  function s0(x){return rotr(2,x)^rotr(13,x)^rotr(22,x);}
  function s1(x){return rotr(6,x)^rotr(11,x)^rotr(25,x);}
  function g0(x){return rotr(7,x)^rotr(18,x)^(x>>>3);}
  function g1(x){return rotr(17,x)^rotr(19,x)^(x>>>10);}
  const K=[0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
  0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
  0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
  0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
  0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
  0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
  0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
  0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
  let H=[0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const bytes=input.slice();
  const bitLen=bytes.length*8;
  bytes.push(0x80);
  while(bytes.length%64!==56) bytes.push(0);
  for(let i=7;i>=0;i--) bytes.push(Math.floor(bitLen/Math.pow(2,i*8))&0xff);
  for(let b=0;b<bytes.length;b+=64){
    const w=new Array(64);
    for(let i=0;i<16;i++) w[i]=(bytes[b+i*4]<<24)|(bytes[b+i*4+1]<<16)|(bytes[b+i*4+2]<<8)|bytes[b+i*4+3];
    for(let i=16;i<64;i++) w[i]=(g1(w[i-2])+w[i-7]+g0(w[i-15])+w[i-16])|0;
    let a=H[0],bb=H[1],cc=H[2],dd=H[3],e=H[4],f=H[5],g=H[6],h=H[7];
    for(let i=0;i<64;i++){
      const t1=(h+s1(e)+ch(e,f,g)+K[i]+w[i])|0;
      const t2=(s0(a)+maj(a,bb,cc))|0;
      h=g;g=f;f=e;e=(dd+t1)|0;dd=cc;cc=bb;bb=a;a=(t1+t2)|0;
    }
    H=[(H[0]+a)|0,(H[1]+bb)|0,(H[2]+cc)|0,(H[3]+dd)|0,(H[4]+e)|0,(H[5]+f)|0,(H[6]+g)|0,(H[7]+h)|0];
  }
  return H.map(x=>((x>>>0).toString(16).padStart(8,'0'))).join('');
}
function utf8Bytes(s){const o=[];for(const c of unescape(encodeURIComponent(String(s)))) o.push(c.charCodeAt(0));return o;}
function hexToBytes(h){const o=[];for(let i=0;i<h.length;i+=2) o.push(parseInt(h.substr(i,2),16));return o;}
function b64ToBytes(str){
  const T='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  const s=String(str).replace(/[^A-Za-z0-9+/]/g,'');
  const o=[];
  for(let i=0;i<s.length;i+=4){
    const c0=T.indexOf(s[i]), c1=T.indexOf(s[i+1]);
    const c2=(i+2<s.length)?T.indexOf(s[i+2]):-1;
    const c3=(i+3<s.length)?T.indexOf(s[i+3]):-1;
    o.push(((c0<<2)|(c1>>4))&255);
    if(c2>=0) o.push(((c1<<4)|(c2>>2))&255);
    if(c3>=0) o.push(((c2<<6)|c3)&255);
  }
  return o;
}
function hmacSha256(keyBytes,msgBytes){
  let k=keyBytes.slice();
  if(k.length>64) k=hexToBytes(sha256Bytes(k));
  while(k.length<64) k.push(0);
  const ip=[],op=[];
  for(let i=0;i<64;i++){ip.push(k[i]^0x36);op.push(k[i]^0x5c);}
  const inner=hexToBytes(sha256Bytes(ip.concat(msgBytes)));
  return sha256Bytes(op.concat(inner));
}

const item = $input.first();
const cabecera = String((item.json.headers || {})['x-hub-signature-256'] || '');
const crudoB64 = (item.binary && item.binary.data) ? item.binary.data.data : null;

function fallo(motivo){
  return [{ json: { firma_ok: false, motivo, body: item.json.body || {} } }];
}

if (!APP_SECRET) return fallo('falta WA_APP_SECRET en el entorno de n8n');
if (!crudoB64) return fallo('no llegó el cuerpo crudo: activa "Raw Body" en el nodo Webhook');
if (!cabecera.startsWith('sha256=')) return fallo('falta la cabecera x-hub-signature-256');

const esperado = hmacSha256(utf8Bytes(APP_SECRET), b64ToBytes(crudoB64));
const recibido = cabecera.slice(7).toLowerCase();

// Comparación en tiempo constante: no filtra información por lo que tarda.
let dif = esperado.length ^ recibido.length;
for (let i = 0; i < esperado.length && i < recibido.length; i++) {
  dif |= esperado.charCodeAt(i) ^ recibido.charCodeAt(i);
}

return [{ json: {
  firma_ok: dif === 0,
  motivo: dif === 0 ? 'ok' : 'la firma no coincide con el App Secret',
  body: item.json.body || {}
} }];

// ── Normaliza el evento de WhatsApp Cloud API ─────────────────────────────
// Un solo POST puede traer VARIOS mensajes y varios cambios de estado a la
// vez. Aquí se aplana a un item por evento, con nombres de campo estables
// que no dependen del proveedor: si mañana cambia el canal, el resto del
// flujo no se entera.
//
// Regla 3 del CLAUDE.md: la identidad es cliente_id (= wa_id), nunca el
//   teléfono formateado ni el LID.
// Regla 4: campo canal en todo, para convivir con Evolution durante la
//   migración.

// Nuestro número sale del entorno, no está escrito en el nodo.
const NUESTRO_NUMERO = $env.WA_PHONE_NUMBER_ID || '';

const body = $json.body || {};
const salida = [];

for (const entry of (body.entry || [])) {
  for (const cambio of (entry.changes || [])) {
    const v = cambio.value || {};
    const meta = v.metadata || {};

    // Una misma app puede tener varios números colgando de la WABA.
    // Marcamos si el evento es del nuestro para poder descartar ruido
    // sin perder el registro (regla 1: guardar siempre).
    const numeroPropio = !NUESTRO_NUMERO || meta.phone_number_id === NUESTRO_NUMERO;

    // Los nombres de perfil llegan aparte, en contacts[], no dentro del mensaje.
    const perfiles = {};
    for (const c of (v.contacts || [])) {
      perfiles[c.wa_id] = (c.profile || {}).name || '';
    }

    for (const m of (v.messages || [])) {
      const adjunto = m[m.type] || {};
      const ref = m.referral || {};
      salida.push({ json: {
        canal:           'whatsapp_cloud',
        tipo_evento:     'mensaje',
        direccion:       'entrante',
        cliente_id:      m.from,
        wa_message_id:   m.id,
        nombre_wa:       perfiles[m.from] || '',
        tipo:            m.type,
        texto:           m.text ? m.text.body : (adjunto.caption || ''),
        media_id:        adjunto.id || null,
        media_mime:      adjunto.mime_type || null,
        // Solo lo traen los documentos. Sin esto el inbox enseña el
        // media_id como nombre de fichero.
        nombre_fichero:  adjunto.filename || null,
        respuesta_a:     (m.context || {}).id || null,
        timestamp:       new Date(Number(m.timestamp) * 1000).toISOString(),
        phone_number_id: meta.phone_number_id || '',
        display_phone:   meta.display_phone_number || '',
        numero_propio:   numeroPropio,
        // Atribución de anuncios click-to-WhatsApp: esto alimenta el CAPI.
        // Solo viene en el PRIMER mensaje. Si se pierde aquí, se pierde
        // para siempre y el pedido queda sin atribuir.
        ctwa_clid:       ref.ctwa_clid || '',
        ad_id:           ref.source_id || '',
        ad_titulo:       ref.headline || '',
        crudo:           m
      }});
    }

    for (const s of (v.statuses || [])) {
      salida.push({ json: {
        canal:           'whatsapp_cloud',
        tipo_evento:     'estado',
        direccion:       'saliente',
        cliente_id:      s.recipient_id,
        wa_message_id:   s.id,
        estado:          s.status,
        timestamp:       new Date(Number(s.timestamp) * 1000).toISOString(),
        phone_number_id: meta.phone_number_id || '',
        numero_propio:   numeroPropio,
        crudo:           s
      }});
    }

    for (const e of (v.errors || [])) {
      salida.push({ json: {
        canal:       'whatsapp_cloud',
        tipo_evento: 'error',
        codigo:      e.code,
        mensaje:     e.title || e.message || '',
        crudo:       e
      }});
    }
  }
}

// Nunca devolvemos vacío: un evento sin reconocer también es información
// y queremos verlo en el historial de ejecuciones.
if (!salida.length) {
  return [{ json: { canal: 'whatsapp_cloud', tipo_evento: 'sin_reconocer', crudo: body } }];
}
return salida;

// Fila para la tabla mensajes.
// Los valores de estado/direccion/autor/tipo estan limitados por CHECK
// constraints; estos son los que el esquema acepta (comprobado contra la
// tabla real, no de memoria):
//   estado    : enviado | entregado | leido | pendiente   (NO existe 'recibido')
//   direccion : in | out
//   autor     : cliente | bot | humano | sistema

const ev = $('Normalizar evento').item.json;

return [{ json: {
  cliente_id:   ev.cliente_id,          // wa_id: la identidad (regla 3)
  canal:        'whatsapp_cloud',       // regla 4
  direccion:    'in',
  autor:        'cliente',
  tipo:         ev.tipo,
  texto:        ev.texto || null,
  estado:       'entregado',   // nos ha llegado
  msg_id_canal: ev.wa_message_id,
  payload:      ev.crudo || null,
  creado:       ev.timestamp,
} }];

// Meta manda sent/delivered/read/failed. El CHECK de la tabla solo
// admite enviado|entregado|leido|pendiente: 'failed' NO tiene destino.
// En vez de tragarnoslo, lo marcamos y se ve en el flujo.
const MAPA = { sent: 'enviado', delivered: 'entregado', read: 'leido' };
const ev = $json;
const equivalente = MAPA[ev.estado] || null;
return [{ json: {
  wa_message_id: ev.wa_message_id,
  estado_meta:   ev.estado,
  estado_supabase: equivalente,
  mapeable:      equivalente !== null,
} }];

// El insert de PostgREST puede devolver un array o un objeto segun el
// Prefer que lleve. Normalizamos aqui para no depender de eso, y caemos
// al evento normalizado si la respuesta no trae lo que esperamos.
const ev = $('Normalizar evento').first().json;
let fila = null;
try {
  const r = $('Guardar mensaje entrante').first().json;
  fila = Array.isArray(r) ? r[0] : r;
} catch (e) {}

// Si el mensaje era un audio y Whisper lo entendio, ESE es el texto que
// ve Maria: entra al buffer y al AI Agent como si lo hubiera escrito.
// El pie de foto (ev.texto) sigue valiendo para imagenes y videos.
let texto = ev.texto || '';
try {
  const a = $('AUDIO decidir').first().json;
  if (a && a.via === 'normal' && a.texto) texto = a.texto;
} catch (e) {}

return [{ json: {
  cliente_id:    (fila && fila.cliente_id)   || ev.cliente_id,
  wa_message_id: (fila && fila.msg_id_canal) || ev.wa_message_id,
  texto,
  nombre_wa:     ev.nombre_wa,
  ctwa_clid:     ev.ctwa_clid,
  ad_id:         ev.ad_id,
} }];

// Convierte la respuesta del GET en un booleano que el IF no pueda
// malinterpretar, y deja escrito POR QUE vale lo que vale.
const r = $json || {};
const codigo = r.statusCode || 0;

// Si el Content-Type no fuera application/json, n8n deja el cuerpo como
// cadena. Lo parseamos por si acaso en vez de fallar en silencio.
let cuerpo = r.body;
if (typeof cuerpo === 'string') { try { cuerpo = JSON.parse(cuerpo); } catch (e) {} }

let bot_activo, motivo, fila = null;

if (codigo < 200 || codigo >= 300) {
  // Supabase no contesto bien. Seguimos atendiendo, pero queda por escrito.
  bot_activo = true;
  motivo = 'no se pudo leer el estado (http ' + codigo + '), por defecto atiende el bot';
} else if (!Array.isArray(cuerpo)) {
  bot_activo = true;
  motivo = 'respuesta inesperada (' + (typeof cuerpo) + '), por defecto atiende el bot';
} else if (cuerpo.length === 0) {
  // Cliente nuevo: nunca estuvo pausado. true es la respuesta correcta,
  // no un valor por defecto.
  bot_activo = true;
  motivo = 'cliente nuevo, sin fila en conversaciones';
} else if (cuerpo.length > 1) {
  // Imposible mientras exista el UNIQUE conversaciones_cliente_id_key,
  // pero si alguien lo quita NO queremos despertar a un cliente pausado.
  bot_activo = false;
  motivo = 'identidad duplicada: ' + cuerpo.length + ' filas para este cliente_id, no respondo';
} else {
  fila = cuerpo[0];
  if ($('Resolver canal').first().json.canal_desconocido === 'si') {
    // Numero sin dar de alta: guardado si, respuesta no. Contestar por
    // un canal que no conocemos es lo unico peor que no contestar.
    bot_activo = false;
    motivo = 'el numero que recibio el mensaje no esta en `canales`';
  } else if ($('Resolver canal').first().json.canal_activo === false) {
    // Canal desactivado desde el inbox: se sigue guardando y viendo,
    // pero no se envia. Es lo que significa desactivar.
    bot_activo = false;
    motivo = 'canal desactivado';
  } else if (fila.bloqueada === true) {
    // Bloqueada en Meta. Si aun llega algo es que el bloqueo todavia no
    // ha surtido efecto: se guarda, pero contestar seria absurdo.
    bot_activo = false;
    motivo = 'cliente bloqueado en WhatsApp';
  } else if (fila.silenciada === true) {
    // Silenciada: entra, se guarda, y hasta ahi. Ni respuesta ni aviso.
    bot_activo = false;
    motivo = 'conversacion silenciada';
  } else if (typeof fila.bot_activo === 'boolean') {
    bot_activo = fila.bot_activo;
    motivo = bot_activo ? 'el bot atiende' : 'pausado: hay un humano al mando';
  } else {
    // La fila existe pero no trae el booleano: callar antes que equivocarse.
    bot_activo = false;
    motivo = 'la fila no trae bot_activo booleano (' + (typeof fila.bot_activo) + ')';
  }
}

const d = $('Datos del mensaje guardado').first().json;
return [{ json: Object.assign({}, d, {
  bot_activo,
  motivo_estado: motivo,
  conversacion_id: (fila && fila.id) || null,
  silenciada: !!(fila && fila.silenciada),
  bloqueada:  !!(fila && fila.bloqueada),
  nombre_conversacion: (fila && fila.nombre) || null,
}) }];

// ADAPTADOR. Emite los mismos nombres de campo que usaba
// "Variables + Interruptor" del v3, para que los nodos trasplantados
// funcionen sin tocarles la logica por dentro.
//
// Diferencia de fondo: la identidad ya no se saca del payload crudo
// (senderPn / remoteJid / LID), sale de cliente_id. Regla 3.

const e = $('Interpretar estado').first().json;
const n = $('Normalizar evento').first().json;
let fichas = '';
try { fichas = String($json.fichas || ''); } catch (err) {}

return [{ json: {
  numero_cliente: e.cliente_id,
  telefono_real:  e.cliente_id,   // ya no hay LID que resolver
  texto_cliente:  e.texto || '',
  nombre_cliente: e.nombre_wa || e.nombre_conversacion || '',
  mensaje_id:     e.wa_message_id,
  ctwa_clid:      e.ctwa_clid || '',
  ad_id:          e.ad_id || '',
  ad_titulo:      n.ad_titulo || '',
  ad_cuerpo:      '',
  fichas,
  conversacion_id: e.conversacion_id || null,
} }];

// Mismo contrato de salida que el "Leer contexto" del v3: { texto }.
// Asi "Añadir contexto" se trasplanta sin tocar una linea.
const r = $json || {};
let cuerpo = r.body;
if (typeof cuerpo === 'string') { try { cuerpo = JSON.parse(cuerpo); } catch (e) {} }
const fila = Array.isArray(cuerpo) && cuerpo.length ? cuerpo[0] : null;
return [{ json: { texto: (fila && fila.texto) || '' } }];

parameters.query:
SELECT COUNT(*)::int AS posteriores
FROM buffer_mensajes
WHERE numero = $1 AND procesado = FALSE AND id > $2;

parameters.jsCode:
// JUNTAR MENSAJES + CONTEXTO DEL ANUNCIO
// 1) Une lo que el cliente escribió durante la ventana del buffer.
// 2) Busca si viene de un anuncio de Meta y, si es así, se lo cuenta a María.

// ---------- 1. Mensajes del buffer ----------
const filas = $input.all()
  .map(i => i.json)
  .filter(f => f && f.texto)
  .sort((a, b) => Number(a.id) - Number(b.id));

const texto = filas.map(f => String(f.texto).trim()).filter(Boolean).join('\n');
const fallback = $('Variables').first().json.texto_cliente || '';
const textoCliente = texto || fallback;

// ---------- 2. Contexto del anuncio ----------
// Busca en cualquier parte del payload, sin dar por hecho la estructura exacta.
function buscarClave(obj, clave, profundidad) {
  profundidad = profundidad || 0;
  if (!obj || typeof obj !== 'object' || profundidad > 8) return null;
  if (obj[clave]) return obj[clave];
  for (const k of Object.keys(obj)) {
    const r = buscarClave(obj[k], clave, profundidad + 1);
    if (r) return r;
  }
  return null;
}

let contexto = '';
let origen = 'ninguno';

try {
  // El v3 buscaba externalAdReply dentro del payload de Evolution.
  // La Cloud API ya nos da la atribución normalizada, así que armamos
  // la misma forma que espera buscarClave() y el resto sigue igual.
  const _v = $('Variables').first().json;
  const body = _v.ad_titulo
    ? { externalAdReply: { title: _v.ad_titulo, body: _v.ad_cuerpo || '' } }
    : {};

  // a) Anuncio de Meta (click-to-WhatsApp)
  const anuncio = buscarClave(body, 'externalAdReply');
  if (anuncio) {
    const partes = [anuncio.title, anuncio.body].filter(Boolean);
    if (partes.length) {
      contexto = partes.join(' — ');
      origen = 'anuncio';
    }
  }

  // b) Respondió citando nuestro saludo automático
  if (!contexto) {
    const citado = buscarClave(body, 'quotedMessage');
    if (citado) {
      const t = citado.conversation
             || (citado.extendedTextMessage && citado.extendedTextMessage.text)
             || (citado.imageMessage && citado.imageMessage.caption);
      if (t) { contexto = String(t); origen = 'saludo citado'; }
    }
  }
} catch (e) {
  contexto = '';
  origen = 'error: ' + e.message;
}

// ---------- 3. Lo que ve María ----------
// El contexto solo se inyecta si existe. Si no, va el mensaje pelado.
const textoParaMaria = contexto
  ? ('[CONTEXTO: este cliente llega desde este anuncio o saludo: "'
      + contexto.slice(0, 300) + '"]\n\n' + textoCliente)
  : textoCliente;

return [{
  json: {
    texto_acumulado: textoCliente,
    texto_para_maria: textoParaMaria,
    contexto_anuncio: contexto,
    origen_contexto: origen,
    mensajes_unidos: filas.length,
    numero_cliente: $('Variables').first().json.numero_cliente,
    nombre_cliente: $('Variables').first().json.nombre_cliente
  }
}];

// AÑADIR CONTEXTO  (+ saneado de entrada)
// Antepone al mensaje del cliente el saludo automático de la campaña.
// IMPORTANTE: primero limpia el texto del cliente de cualquier marcador
// interno. Si no, un cliente puede escribir [CONTEXTO: ...] o [PEDIDO]
// y María lo interpretaría como instrucción del sistema.

const base = $('Juntar mensajes').first().json;

// ---------- SANEADO ----------
function sanear(t) {
  return String(t || '')
    // marcadores internos que solo el sistema puede emitir
    .replace(/\[\s*\/?\s*(CONTEXTO|PEDIDO|PEDIDO_COMPLETO|FOTO|FOTO_OFERTA|ESCALAR)\b[^\]]*\]/gi, '')
    // corchetes sueltos que imiten la sintaxis
    .replace(/\[\/?[A-Z_]{4,}\s*:?[^\]]{0,80}\]/g, '')
    // intentos clásicos de reescribir el rol
    .replace(/^\s*(system|assistant|developer)\s*:/gim, '')
    .trim();
}

// Techo de longitud: un mensaje enorme dispara el coste por tokens
const MAX = 1500;
let textoCliente = sanear(base.texto_acumulado);
if (textoCliente.length > MAX) textoCliente = textoCliente.slice(0, MAX) + ' […]';

// ---------- CONTEXTO ----------
let contexto = '';
let origen = 'ninguno';

try {
  const fila = $('Leer contexto').first().json;
  if (fila && fila.texto) { contexto = String(fila.texto); origen = 'saludo automatico'; }
} catch (e) {}

if (!contexto && base.contexto_anuncio) {
  contexto = base.contexto_anuncio;
  origen = base.origen_contexto || 'webhook';
}

// El contexto también se sanea: viene de un mensaje, no de nosotros
contexto = sanear(contexto).replace(/\s+/g, ' ').slice(0, 300);

// Fichas de presentación ya enviadas a este cliente
let yaEnviadas = '';
try { yaEnviadas = String($('Variables').first().json.fichas || '').trim(); } catch (e) {}
const avisoFichas = yaEnviadas
  ? ('[FICHAS_YA_ENVIADAS: ' + yaEnviadas + ']\n')
  : '';

const textoParaMaria = contexto
  ? (avisoFichas + '[CONTEXTO: este cliente llega desde este anuncio o saludo: "'
      + contexto + '"]\n\n' + textoCliente)
  : (avisoFichas ? avisoFichas + '\n' + textoCliente : textoCliente);

return [{
  json: {
    ...base,
    texto_acumulado: textoCliente,
    contexto_detectado: contexto,
    origen_contexto: origen,
    texto_para_maria: textoParaMaria
  }
}];

// PREPARAR CATÁLOGO - convierte las filas de productos en texto para María
// Lee todos los items del nodo 'Leer Catálogo', filtra los activos, y arma un texto ordenado.

const items = $('Leer Catálogo').all();
let catalogo = '=== CATÁLOGO DE PRODUCTOS DISPONIBLES ===\n\n';
let contador = 0;

for (const item of items) {
  const p = item.json;
  // Solo productos activos
  if (String(p.activo).trim().toUpperCase() !== 'SI') continue;
  contador++;

  catalogo += `PRODUCTO ${contador} (id: ${p.id})\n`;
  catalogo += `Nombre: ${p.nombre}\n`;
  catalogo += `Palabras que usa el cliente: ${p.palabras_clave}\n`;
  catalogo += `Precio: $${p.precio}`;
  if (p.precio_antes && String(p.precio_antes) !== String(p.precio)) {
    catalogo += ` (antes $${p.precio_antes})`;
  }
  catalogo += `\n`;

  // OFERTA: si el campo trae algo, María DEBE mencionarla al dar el precio.
  //         Si está vacío, dice solo el precio y nada más.
  if (p.ofertas && String(p.ofertas).trim()) {
    const lista = String(p.ofertas).split('|').map(o => o.trim()).filter(Boolean);
    catalogo += `>>> ESTE PRODUCTO TIENE OFERTA. ES OBLIGATORIO MENCIONARLA\n`;
    catalogo += `>>> SIEMPRE QUE DIGAS EL PRECIO, SIN EXCEPCIÓN:\n`;
    for (const o of lista) catalogo += `>>>   * ${o}\n`;
  } else {
    catalogo += `>>> ESTE PRODUCTO NO TIENE OFERTA.\n`;
    catalogo += `>>> Di únicamente el precio de arriba. NO inventes ninguna promoción,\n`;
    catalogo += `>>> ni descuento por cantidad, ni envío especial, ni regalo.\n`;
  }

  catalogo += `Beneficios: ${p.beneficios}\n`;
  catalogo += `Descripción: ${p.descripcion}\n`;
  if (p.colores) catalogo += `Colores: ${p.colores}\n`;
  if (p.entrega) catalogo += `Entrega: ${p.entrega}\n`;
  if (p.info_extra) catalogo += `Info adicional: ${p.info_extra}\n`;
  catalogo += `Foto (señal para enviarla): [FOTO:${p.id}]\n`;
  if (p.ficha_texto && String(p.ficha_texto).trim()) {
    catalogo += `>>> Este producto TIENE ficha de presentación: [FICHA:${p.id}]\n`;
  }
  catalogo += `\n---\n\n`;
}

if (contador === 0) {
  catalogo += '(No hay productos activos en este momento.)\n';
}

return [{ json: { catalogo_texto: catalogo } }];

// ¿TOCA FICHA?  — decisión determinista, sin llamar al modelo
//
// Se envía la ficha si se cumplen las TRES condiciones:
//   1. El cliente no ha recibido ya la ficha de ese producto
//   2. Se identifica el producto: por el mensaje del cliente O por el
//      saludo automático del anuncio de Meta
//   3. Es una consulta general (precio, info, entrega, pago...) o el
//      cliente muestra intención de pedir

function normalizar(t) {
  return String(t || '')
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')   // quita acentos
    .replace(/[^a-z0-9ñ\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const base = $('Juntar mensajes').first().json;
const mensaje = normalizar(base.texto_acumulado);

// Contexto: hay DOS fuentes posibles y se revisan las dos.
//  a) el saludo automático de la campaña (guardado en contexto_cliente)
//  b) el anuncio de Meta que viene en el propio webhook (externalAdReply:
//     título y texto del anuncio). A menudo el saludo es genérico pero el
//     anuncio sí nombra el producto.
let contextoSaludo = '';
let contextoAnuncio = '';
try { contextoSaludo = normalizar($('Añadir contexto').first().json.contexto_detectado); } catch (e) {}
try { contextoAnuncio = normalizar($('Juntar mensajes').first().json.contexto_anuncio); } catch (e) {}
const contexto = (contextoSaludo + ' ' + contextoAnuncio).trim();

// ---------- fichas que este cliente ya recibió ----------
let yaEnviadas = [];
try {
  yaEnviadas = String($('Variables').first().json.fichas || '')
    .split(',').map(s => s.trim()).filter(Boolean);
} catch (e) {}

// ---------- ¿qué quiere? ----------
const consultaGeneral = [
  'precio', 'precios', 'cuanto', 'cuanto cuesta', 'cuanto vale', 'cuanto sale',
  'costo', 'cuesta', 'vale', 'valor',
  'info', 'informacion', 'informes', 'detalles',
  'me interesa', 'interesa', 'quiero saber', 'quiero informacion',
  'cuenteme', 'cuentame', 'cuenteme mas', 'digame',
  'como funciona', 'para que sirve', 'de que se trata', 'como es',
  'promocion', 'promociones', 'oferta', 'ofertas', 'descuento',
  'envio', 'envios', 'entrega', 'mandan', 'hacen envio', 'hacen envios', 'llega',
  'cuanto tarda', 'cuanto tarda la entrega',
  'pago', 'pagar', 'se paga', 'como se paga', 'forma de pago', 'metodo de pago',
  'disponible', 'disponibilidad', 'tienen', 'hay'
];

// Intención de pedir: también merece ver la ficha antes de dar sus datos
const intencionPedir = [
  'quiero ordenar', 'quiero pedir', 'quiero comprar', 'quiero uno', 'quiero dos',
  'ordenar ya', 'pedir ya', 'lo quiero', 'la quiero', 'me lo llevo',
  'como lo pido', 'como hago el pedido', 'como ordeno', 'quisiera pedir'
];

let esGeneral = consultaGeneral.some(f => mensaje.includes(f))
             || intencionPedir.some(f => mensaje.includes(f));

// Saludo suelto o mensaje muy corto, cuando el anuncio ya dice el producto
const muyCorto = mensaje.split(' ').length <= 4;

// ---------- ¿qué producto? ----------
// Primero en el mensaje del cliente. Si no aparece, en el contexto del anuncio.
// Devuelve TODOS los productos que coinciden, con la longitud de la
// palabra clave que los identificó. Si coincide más de uno, hay duda.
// MODO ESTRICTO (para saludo y anuncio): solo valen las palabras clave
// COMPUESTAS, de dos palabras o más ("mini luces", "soporte inteligente").
// Una palabra suelta como "luces", "soporte" o "carga" aparece por
// casualidad en cualquier texto publicitario y provoca falsos positivos.
//
// MODO NORMAL (para el mensaje del cliente): vale cualquier palabra clave,
// porque la gente escribe "cepillo" o "sporte" a secas.
function buscarProductos(texto, minLargo, estricto) {
  const encontrados = [];
  if (!texto) return encontrados;
  for (const item of $('Leer Catálogo').all()) {
    const fila = item.json;
    if (String(fila.activo).trim().toUpperCase() !== 'SI') continue;
    if (!String(fila.ficha_texto || '').trim()) continue;
    const id = String(fila.id).trim();
    if (yaEnviadas.includes(id)) continue;

    let claves = String(fila.palabras_clave || '')
      .split(',').map(s => normalizar(s)).filter(s => s.length >= minLargo);

    // El nombre completo del producto siempre vale: es único de ese producto.
    const nombreCompleto = normalizar(fila.nombre);
    if (nombreCompleto.length >= minLargo) claves.push(nombreCompleto);

    if (estricto) {
      // Solo expresiones de DOS PALABRAS O MÁS
      claves = claves.filter(k => k.split(' ').length >= 2);
    } else {
      // Mensaje del cliente: también las palabras largas del nombre
      claves.push(...nombreCompleto.split(' ').filter(s => s.length >= 6));
    }

    let largo = 0;
    for (const clave of claves) {
      if (clave && texto.includes(clave) && clave.length > largo) largo = clave.length;
    }
    if (largo > 0) encontrados.push({ fila, largo });
  }
  return encontrados.sort((a, b) => b.largo - a.largo);
}

// --- 1) El mensaje del cliente manda ---
let producto = null;
let origen = 'ninguno';

const enMensaje = buscarProductos(mensaje, 4, false);   // mensaje: modo normal
if (enMensaje.length === 1 ||
    (enMensaje.length > 1 && enMensaje[0].largo > enMensaje[1].largo)) {
  producto = enMensaje[0].fila;
  origen = 'mensaje';
}

// --- 2) Si no, los contextos, con criterio estricto ---
// Se prueba cada fuente por separado (el anuncio de Meta suele ser la
// que nombra el producto aunque el saludo sea genérico).
// Solo vale si identifica UN producto sin ninguna duda. Si es genérico
// o encaja con varios, NO se envía ficha: María preguntará.
if (!producto) {
  // Se consulta cada fuente y se anotan los candidatos.
  // El SALUDO va primero: es nuestra propia plantilla y nombra el producto
  // de forma explícita. El anuncio del webhook es secundario.
  const candidatos = [];
  for (const [nombreFuente, fuente] of [['saludo', contextoSaludo], ['anuncio', contextoAnuncio]]) {
    if (!fuente) continue;
    const enCtx = buscarProductos(fuente, 6, true);         // contexto: modo estricto
    if (enCtx.length === 1 && enCtx[0].largo >= 6) {
      candidatos.push({ fuente: nombreFuente, id: String(enCtx[0].fila.id).trim(), fila: enCtx[0].fila });
    }
  }

  // Si dos fuentes señalan productos DISTINTOS, hay contradicción:
  // no se envía ninguna ficha. María preguntará qué producto le interesa.
  const idsDistintos = [...new Set(candidatos.map(x => x.id))];
  if (idsDistintos.length > 1) {
    return [{ json: {
      enviar_ficha: false,
      motivo: 'contradiccion entre fuentes: ' + candidatos.map(x => x.fuente + '=' + x.id).join(' / ')
    } }];
  }
  if (candidatos.length > 0) {
    producto = candidatos[0].fila;
    origen = candidatos[0].fuente;
  }
}

// ---------- decisión ----------
const enviar = Boolean(producto) && (esGeneral || muyCorto || origen === 'anuncio');

if (!enviar) {
  return [{ json: {
    enviar_ficha: false,
    _saludo: contextoSaludo.slice(0, 200),
    _anuncio: contextoAnuncio.slice(0, 200),
    motivo: producto ? 'no es consulta general' : 'producto no identificado con seguridad'
  } }];
}

const imagen = (producto.ficha_url && String(producto.ficha_url).trim())
             || (producto.foto_url  && String(producto.foto_url).trim())
             || '';
const texto = String(producto.ficha_texto).trim();

if (!imagen) return [{ json: { enviar_ficha: false, motivo: 'sin imagen en el catalogo' } }];

return [{
  json: {
    enviar_ficha: true,
    id_producto: String(producto.id).trim(),
    origen_producto: origen,
    _saludo: contextoSaludo.slice(0, 200),
    _anuncio: contextoAnuncio.slice(0, 200),
    imagen,
    texto,
    numero_cliente: ($('Variables').first().json.telefono_real
                 || $('Variables').first().json.numero_cliente)
  }
}];

// FILTRO DE SEGURIDAD v5 — anti extracción
// Dos capas independientes:
//   A) qué PIDIÓ el cliente  -> si es un intento de sacar el prompt, la
//      respuesta de María se descarta pase lo que pase.
//   B) qué RESPONDIÓ María   -> aunque la pregunta pareciera inocente.

const salida  = $('AI Agent').item.json.output || '';
const entrada = ($('Añadir contexto').first().json.texto_acumulado || '').toLowerCase();

// ---------- Limpieza de señales internas ----------
let respuesta = salida
  .replace(/\[PEDIDO\][\s\S]*?\[\/PEDIDO\]/gi, '')
  .replace(/\[PEDIDO_COMPLETO\][\s\S]*?\[\/PEDIDO_COMPLETO\]/gi, '')
  .replace(/\[FICHA:[a-zA-Z0-9_-]+\]/gi, '')
  .replace(/\[FOTO:[a-zA-Z0-9_-]+\]/gi, '')
  .replace(/\[FOTO_OFERTA\]/gi, '')
  .replace(/\[ESCALAR:[\s\S]*?\]/gi, '')
  .trim();

const texto = respuesta.toLowerCase();

// ¿La salida era ÚNICAMENTE un [ESCALAR:...]?  -> escalado silencioso:
// se avisa al grupo pero NO se envía nada al cliente.
const teniaEscalar = /\[ESCALAR:/i.test(salida);
const soloEscalar  = teniaEscalar && respuesta.length === 0;

// ¿Emitió un [PEDIDO]? -> silencio TOTAL hacia el cliente. Aunque el
// modelo escribiera texto alrededor del bloque, no se envía nada:
// solo el aviso al grupo. El equipo humano se encarga desde ahí.
const teniaPedido = /\[PEDIDO\]/i.test(salida);

// ============================================================
// PROHIBIDO ENUMERAR EL CATÁLOGO
// Si la respuesta menciona DOS O MÁS productos distintos del catálogo,
// se descarta entera y se sustituye por la pregunta neutra.
// Nunca se revela a un cliente (o competidor) qué vendemos.
// ============================================================
function normalizarCat(t) {
  return String(t || '').toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9ñ\s]/g, ' ').replace(/\s+/g, ' ').trim();
}
let productosMencionados = 0;
try {
  const respNorm = normalizarCat(respuesta);
  for (const item of $('Leer Catálogo').all()) {
    const fila = item.json;
    if (String(fila.activo).trim().toUpperCase() !== 'SI') continue;
    // firma del producto: las palabras largas de su nombre
    const firmas = normalizarCat(fila.nombre).split(' ').filter(w => w.length >= 5);
    firmas.push(normalizarCat(fila.id));
    if (firmas.some(f => f && respNorm.includes(f))) productosMencionados++;
  }
} catch (e) {}

const enumeraCatalogo = productosMencionados >= 2;

let bloqueado = false;
let motivo = '';

if (enumeraCatalogo) {
  bloqueado = true;
  motivo = 'enumera varios productos del catalogo';
}

// ================= CAPA A: intención del cliente =================
// Frases completas, no palabras sueltas: "instrucciones de uso del cepillo"
// o "¿qué modelo de cepillo?" son preguntas legítimas de venta.
const intentosExtraccion = [
  'tu prompt', 'el prompt', 'system prompt', 'prompt del sistema',
  'tus instrucciones', 'las instrucciones que te', 'instrucciones del sistema',
  'tus reglas', 'las reglas que te', 'tu configuracion', 'tu configuración',
  'como estas programad', 'cómo estás programad', 'como te programaron',
  'que modelo eres', 'qué modelo eres', 'modelo de lenguaje', 'que ia eres',
  'eres un bot', 'eres una ia', 'eres un robot', 'eres humano',
  'ignora las instrucciones', 'ignora lo anterior', 'olvida tus',
  'olvida las instrucciones', 'a partir de ahora eres', 'actua como si',
  'actúa como si', 'modo desarrollador', 'modo debug', 'jailbreak',
  'repite todo lo que', 'repite tus', 'muestrame tus', 'muéstrame tus',
  'dime tus instrucciones', 'imprime tus', 'traduce tus instrucciones',
  'resume tus instrucciones', 'cual es tu prompt', 'cuál es tu prompt',
  'api key', 'apikey', 'clave api', 'credenciales', 'contraseña de',
  'base de datos', 'postgres', 'webhook', 'n8n', 'openai', 'chatgpt',
  'quien te creo', 'quién te creó', 'que hay antes de este mensaje',
  'texto anterior a', 'primer mensaje del sistema'
];

for (const frase of intentosExtraccion) {
  if (entrada.includes(frase)) {
    bloqueado = true;
    motivo = 'intento de extraccion: "' + frase + '"';
    break;
  }
}

// ================= CAPA B: qué iba a contestar =================
if (!bloqueado) {
  const señalesPeligro = [
    'system message', 'system prompt', 'mis instrucciones son', 'mi prompt',
    'mi configuracion', 'regla de seguridad', 'maxima prioridad',
    'claude', 'anthropic', 'openai', 'chatgpt', 'gpt-', 'modelo de lenguaje',
    'soy una ia', 'soy un bot', 'soy una inteligencia artificial',
    'language model', 'como asistente de ia', 'mis reglas son',
    'instrucciones confidenciales', 'no debo revelar', 'ignora lo anterior',
    'estas instrucciones', 'catalogo de productos disponibles',
    // marcas propias del prompt: si salen, está volcando el documento
    'regla de oro', 'muy importante:', 'prohibido', 'cosas que nunca haces',
    'paso 1', 'paso 2', 'paso 3', 'paso 4', 'paso 5', 'paso 6',
    'ejemplo exacto', 'contexto:', 'pedido]', 'escalar:',
    'n8n', 'postgres', 'webhook', 'api key', 'apikey', 'credencial'
  ];
  for (const señal of señalesPeligro) {
    if (texto.includes(señal)) { bloqueado = true; motivo = 'fuga: ' + señal; break; }
  }
}

// ================= CAPA C: heurísticas de volcado =================
if (!bloqueado) {
  // un prompt volcado trae muchas líneas; una respuesta de venta no
  const lineas = respuesta.split('\n').filter(l => l.trim()).length;
  if (lineas > 14)            { bloqueado = true; motivo = 'demasiadas lineas'; }
  else if (respuesta.length > 1200) { bloqueado = true; motivo = 'respuesta demasiado larga'; }
}

// ================= Nunca confirma pedidos por su cuenta =================
if (!bloqueado) {
  const frasesConfirmacion = [
    'su pedido quedo registrado', 'su pedido ha sido registrado',
    'pedido registrado', 'orden registrada', 'su orden quedo',
    'ya registre su pedido', 'queda registrado'
  ];
  for (const f of frasesConfirmacion) {
    if (texto.includes(f)) { bloqueado = true; motivo = 'confirmo pedido por su cuenta'; break; }
  }
}

if (!respuesta && !soloEscalar) { bloqueado = true; motivo = 'respuesta vacia'; }

// Respuesta neutra: no confirma ni desmiente nada, y reconduce a la venta
const mensajeSeguro = enumeraCatalogo
  ? 'Con gusto le ayudo 😊 ¿Qué producto le interesa?'
  : 'Disculpe, no le entendí bien 😊 ¿Sobre qué producto quiere que le ayude?';

return [{
  json: {
    respuesta_final: bloqueado ? mensajeSeguro : respuesta,
    solo_escalar: soloEscalar || teniaPedido,
    bloqueado,
    motivo_bloqueo: motivo,
    numero_cliente: $('Variables').item.json.numero_cliente
  }
}];

// PREPARAR PEDIDO
// Ya no interpretamos la dirección. Cogemos el producto (que María sí sabe)
// y le mandamos al dueño el texto tal cual lo escribió el cliente.

const salida = $('AI Agent').item.json.output || '';
const numero = $('Variables').first().json.telefono_real
            || $('Variables').first().json.numero_cliente;
const nombreWa = $('Variables').first().json.nombre_cliente || '';

// Lo que escribió el cliente en esta tanda (el buffer ya lo unió)
const datosCliente = ($('Juntar mensajes').first().json.texto_acumulado || '').trim();

// Del bloque solo sacamos producto / cantidad / precio
const bloque = (salida.match(/\[PEDIDO\]([\s\S]*?)\[\/PEDIDO\]/i) || [])[1] || '';
// Funciona aunque María escriba todo el bloque en una sola línea:
// se corta en la siguiente etiqueta conocida, no en el salto de línea.
function campo(nombre) {
  const re = new RegExp(
    nombre + '\\s*:\\s*([\\s\\S]*?)(?=\\s*(?:producto|cantidad|precio|total)\\s*:|\\s*\\[\\/?PEDIDO|$)',
    'i');
  const m = bloque.match(re);
  return m ? m[1].replace(/[\s,;.]+$/, '').trim() : '';
}

// Normaliza el precio: "$1,485" -> 1485  (para poder sumar después)
function soloNumero(v) {
  const n = String(v || '').replace(/[^0-9.]/g, '').replace(/\.(?=.*\.)/g, '');
  return n === '' ? '' : String(Math.round(parseFloat(n)));
}

// ── DE DONDE SALE EL PRODUCTO ────────────────────────────────────────
// Nunca del texto del modelo a pelo. Se empareja contra el catalogo con
// la MISMA normalizacion que usa "Decidir ficha", para que identificar
// una ficha y registrar un pedido no puedan dar resultados distintos.
function normalizar(t) {
  return String(t || '').toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9ñ\s]/g, ' ').replace(/\s+/g, ' ').trim();
}

// OJO: aqui NO se excluyen los productos con ficha ya enviada, al reves
// que en "Decidir ficha". Que el cliente que compra ya tuviera la ficha
// es el caso NORMAL: excluirlo dejaria sin identificar justo los pedidos
// buenos. Es el mismo error que ya nos comimos una vez con la ficha.
function emparejar(texto) {
  const t = normalizar(texto);
  if (!t) return [];
  const out = [];
  for (const item of $('Leer Catálogo').all()) {
    const f = item.json;
    const id = String(f.id || "").trim();
    if (!id) continue;
    const claves = String(f.palabras_clave || '').split(',')
      .map(normalizar).filter(s => s.length >= 4);
    const nombre = normalizar(f.nombre);
    if (nombre.length >= 4) claves.push(nombre);
    claves.push(...nombre.split(' ').filter(s => s.length >= 6));
    let largo = 0;
    for (const c of claves) if (c && t.includes(c) && c.length > largo) largo = c.length;
    if (largo > 0) out.push({ id, nombre: String(f.nombre).trim(), largo });
  }
  return out.sort((a, b) => b.largo - a.largo);
}

// Un empate es una duda, y una duda no se resuelve inventando.
function unico(c) {
  if (!c.length) return null;
  if (c.length === 1) return c[0];
  return c[0].largo > c[1].largo ? c[0] : null;
}

// Tres fuentes, de mas a menos fiable:
//  1. Lo que el modelo puso en [PEDIDO] producto: — casi siempre copia el
//     nombre del catalogo, solo que con la cantidad y el precio pegados.
//  2. La ficha que recibio este cliente, si recibio UNA sola.
//  3. Lo que escribio el cliente en esta tanda.
let elegido = unico(emparejar(campo('producto')));

if (!elegido) {
  let fichas = [];
  try { fichas = String($('Variables').first().json.fichas || '')
    .split(',').map(s => s.trim()).filter(Boolean); } catch (e) {}
  if (fichas.length === 1) {
    for (const item of $('Leer Catálogo').all()) {
      if (String(item.json.id || "").trim() === fichas[0]) {
        elegido = { id: fichas[0], nombre: String(item.json.nombre).trim() };
        break;
      }
    }
  }
}

if (!elegido) elegido = unico(emparejar(datosCliente));

const producto_id = elegido ? elegido.id : null;
const producto = elegido ? elegido.nombre : '⚠️ No confirmado — ver conversación';
const cantidad = campo('cantidad') || '1';
const precioTexto = campo('precio') || 'No indicado';
const precio      = soloNumero(precioTexto) || precioTexto;

// Enlace directo al chat del cliente
const soloDigitos = String(numero).replace(/\D/g, '');
const enlaceChat = 'https://wa.me/' + soloDigitos;

const aviso = [
  '🛒🛒🛒 *NUEVO PEDIDO* 🛒🛒🛒',
  '📱 Cliente: ' + numero,
  '📦 Producto: ' + producto,
  '💬 Abrir chat: ' + enlaceChat
].join('\n');

const confirmacion = [
  '¡Listo! 🎉 Su pedido quedó registrado.',
  '',
  'Le llega a domicilio y paga en efectivo al recibirlo. Nuestro repartidor le marcará antes de llegar.',
  '',
  '¡Gracias por su compra! 😊'
].join('\n');

return [{
  json: {
    numero_cliente: numero,
    precio_texto: precioTexto,
    nombre_wa: nombreWa,
    enlace_chat: enlaceChat,
    producto, cantidad, precio,
    // El id del catalogo. null = no se pudo identificar, y entonces
    // NO se marca el producto: mejor un hueco que un dato inventado.
    producto_id,
    datos_cliente: datosCliente,
    aviso_pedido: aviso,
    confirmacion_cliente: confirmacion
  }
}];

