parameters.jsCode:
// PROCESAR FOTO POR PRODUCTO
// La señal [FOTO:id] se busca en la salida CRUDA del AI Agent, porque el
// Filtro Seguridad ya la ha eliminado del texto que ve el cliente.
// El texto limpio sí viene del Filtro.

const salidaCruda = $('AI Agent').item.json.output || '';
const textoLimpio = ($('Filtro Seguridad').item.json.respuesta_final || '').trim();

// Buscar la señal en la salida cruda
const match = salidaCruda.match(/\[FOTO:([a-zA-Z0-9_-]+)\]/i);

let hayFoto = false;
let fotoUrl = '';
let idProducto = '';

if (match) {
  idProducto = match[1];
  const productos = $('Leer Catálogo').all();
  for (const item of productos) {
    if (String(item.json.id).trim() === idProducto) {
      fotoUrl = String(item.json.foto_url || '').trim();
      break;
    }
  }
  hayFoto = fotoUrl !== '';
}

return [{
  json: {
    texto_final: textoLimpio,
    hay_foto: hayFoto,
    foto_url: fotoUrl,
    id_producto: idProducto,
    numero_cliente: $('Variables').item.json.numero_cliente
  }
}];

// PREPARAR ENVÍO HUMANO
// Trocea la respuesta y calcula cuánto "tarda en escribir" cada trozo.
// Los retardos son ACUMULATIVOS: si no, Evolution suelta antes el mensaje
// corto y los trozos llegan desordenados.

const texto  = ($('Procesar Foto').item.json.texto_final || '').trim();
const numero = $('Variables').first().json.telefono_real
            || $('Variables').first().json.numero_cliente;

// --- 1. Trocear ---
// SOLO partimos donde María puso |||.
// Nunca partimos por nuestra cuenta: rompería las listas numeradas.
let trozos = texto.includes('|||') ? texto.split('|||') : [texto];

trozos = trozos.map(t => t.replace(/\|\|\|/g, '').trim()).filter(Boolean);

// --- 1b. Red de seguridad: reponer saltos de línea en las ofertas ---
// Si María escribe la lista de opciones seguida en un párrafo, la desdoblamos.
function arreglarOferta(t) {
  // ¿trae opciones numeradas del tipo *1.* o *2)* pegadas a otro texto?
  if (!/\*\s*\d+\s*[.)]\s*\*/.test(t)) return t;
  return t
    // salto antes de cada opción numerada que no esté ya al principio de línea
    .replace(/(?!^)[ \t]*(\*\s*\d+\s*[.)]\s*\*)/gm, '\n$1')
    // salto antes de la pregunta final
    .replace(/([^\n])[ \t]+(¿(?:Cuál|Cual|Qué|Que)\b)/g, '$1\n$2')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}
trozos = trozos.map(arreglarOferta);

// Nunca más de 3 mensajes seguidos: el resto se une al tercero
if (trozos.length > 3) {
  trozos = [trozos[0], trozos[1], trozos.slice(2).join('\n\n')];
}

if (trozos.length === 0) trozos = ['¡Gracias! 😊'];

// --- 2. Tiempo de escritura, acumulado ---
// ~60 ms por carácter, con suelo de 1,5 s y techo de 6,5 s por trozo.
function tiempoEscritura(t) {
  return Math.min(Math.max(Math.round(t.length * 60), 1500), 6500);
}

let acumulado = 0;
return trozos.map((t, i) => {
  acumulado += tiempoEscritura(t);
  return {
    json: {
      number: numero,
      texto: t,
      delay: acumulado,          // <- clave: cada trozo espera también lo anterior
      parte: i + 1,
      total_partes: trozos.length
    }
  };
});

// FILA DE INCIDENCIA — escalado de María
// Se ejecuta en paralelo al aviso al grupo. Si Google falla, el aviso sale igual.

function ahora() {
  return new Date().toLocaleString('es-MX', {
    timeZone: 'America/Mexico_City',
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit'
  });
}

const salida = $('AI Agent').item.json.output || '';
const m = salida.match(/\[ESCALAR:\s*([\s\S]*?)\]/i);
const motivo = m ? m[1].trim() : 'sin motivo indicado';

const vars = $('Variables').first().json;
let telefono = vars.numero_cliente;
try { telefono = $('Variables').first().json.telefono_real || telefono; } catch (e) {}

let mensajeCliente = '';
try { mensajeCliente = $('Juntar mensajes').first().json.texto_acumulado || ''; } catch (e) {}

// Producto del que se hablaba, si se puede saber
let producto = '';
try {
  const texto = (mensajeCliente + ' ' + salida).toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  for (const item of $('Leer Catálogo').all()) {
    const fila = item.json;
    if (String(fila.activo).trim().toUpperCase() !== 'SI') continue;
    const claves = String(fila.palabras_clave || '').split(',')
      .map(s => s.trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, ''))
      .filter(s => s.length >= 5);
    if (claves.some(k => k && texto.includes(k))) { producto = fila.nombre; break; }
  }
} catch (e) {}

// De dónde venía el cliente
let contexto = '';
try { contexto = String($('Añadir contexto').first().json.contexto_detectado || '').slice(0, 300); } catch (e) {}

return [{ json: {
  fecha_hora: ahora(),
  telefono: String(telefono),
  nombre_wa: vars.nombre_cliente || '',
  tipo: 'escalado',
  motivo,
  mensaje_cliente: mensajeCliente.slice(0, 500),
  producto,
  contexto,
  estado: ''
} }];

// EVENTO DE COMPRA PARA META (API de Conversiones)
// Se dispara cuando entra un pedido. Usa el ctwa_clid capturado en el
// primer mensaje del cliente: eso da atribución EXACTA al anuncio.

// SHA-256 en JavaScript puro: n8n bloquea el módulo 'crypto'
function sha256(msg) {
  function rotr(n,x){return (x>>>n)|(x<<(32-n));}
  function ch(x,y,z){return (x&y)^(~x&z);}
  function maj(x,y,z){return (x&y)^(x&z)^(y&z);}
  function s0(x){return rotr(2,x)^rotr(13,x)^rotr(22,x);}
  function s1(x){return rotr(6,x)^rotr(11,x)^rotr(25,x);}
  function g0(x){return rotr(7,x)^rotr(18,x)^(x>>>3);}
  function g1(x){return rotr(17,x)^rotr(19,x)^(x>>>10);}
  const K=[0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
  0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
  0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
  0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
  0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
  0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
  0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
  0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
  let H=[0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const bytes=[];
  for(const cp of unescape(encodeURIComponent(msg))) bytes.push(cp.charCodeAt(0));
  const bitLen=bytes.length*8;
  bytes.push(0x80);
  while(bytes.length%64!==56) bytes.push(0);
  for(let i=7;i>=0;i--) bytes.push((bitLen/Math.pow(2,i*8))&0xff);
  for(let b=0;b<bytes.length;b+=64){
    const w=new Array(64);
    for(let i=0;i<16;i++) w[i]=(bytes[b+i*4]<<24)|(bytes[b+i*4+1]<<16)|(bytes[b+i*4+2]<<8)|bytes[b+i*4+3];
    for(let i=16;i<64;i++) w[i]=(g1(w[i-2])+w[i-7]+g0(w[i-15])+w[i-16])|0;
    let a=H[0],bb=H[1],cc=H[2],dd=H[3],e=H[4],f=H[5],g=H[6],h=H[7];
    for(let i=0;i<64;i++){
      const t1=(h+s1(e)+ch(e,f,g)+K[i]+w[i])|0;
      const t2=(s0(a)+maj(a,bb,cc))|0;
      h=g;g=f;f=e;e=(dd+t1)|0;dd=cc;cc=bb;bb=a;a=(t1+t2)|0;
    }
    H=[(H[0]+a)|0,(H[1]+bb)|0,(H[2]+cc)|0,(H[3]+dd)|0,(H[4]+e)|0,(H[5]+f)|0,(H[6]+g)|0,(H[7]+h)|0];
  }
  return H.map(x=>((x>>>0).toString(16).padStart(8,'0'))).join('');
}

const pedido = $('Preparar pedido').first().json;

let clid = '', adId = '', telefono = '';
try {
  const est = $('Variables').first().json;
  clid     = String(est.ctwa_clid || '');
  adId     = String(est.ad_id || '');
  telefono = String(est.telefono_real || '');
} catch (e) {}

if (!telefono) telefono = String(pedido.numero_cliente || '');

// Sin clid la atribución sería muy pobre: mejor no ensuciar el dataset.
if (!clid) {
  return [{ json: { enviar: false, motivo: 'sin ctwa_clid: el cliente no vino de un anuncio' } }];
}

// Valor: solo el número, tal y como se guarda en la tabla pedidos
const valor = parseFloat(String(pedido.precio).replace(/[^0-9.]/g, '')) || 0;

const evento = {
  data: [{
    event_name: 'Purchase',
    event_time: Math.floor(Date.now() / 1000),
    action_source: 'business_messaging',
    messaging_channel: 'whatsapp',
    event_id: 'pedido-' + (pedido.numero_cliente || '') + '-' + Math.floor(Date.now() / 1000),
    user_data: {
      ctwa_clid: clid,
      ph: [sha256(String(telefono).replace(/\D/g, '').trim())]
    },
    custom_data: {
      currency: 'MXN',
      value: valor,
      content_name: pedido.producto || '',
      num_items: parseInt(pedido.cantidad, 10) || 1,
      order_id: 'wa-' + (pedido.numero_cliente || '') + '-' + Math.floor(Date.now() / 1000)
    }
  }]
};

return [{ json: { enviar: true, evento, clid, ad_id: adId, valor } }];

// Mismo contrato que la consulta vieja a pausados: { pausado: 0|1 }.
// Asi el IF que viene detras se trasplanta sin tocarlo.
const r = $json || {};
let c = r.body;
if (typeof c === 'string') { try { c = JSON.parse(c); } catch (e) {} }
const fila = Array.isArray(c) && c.length ? c[0] : null;
// Si no se puede leer, asumimos NO pausado y seguimos (igual que antes).
const activo = fila ? fila.bot_activo !== false : true;
return [{ json: { pausado: activo ? 0 : 1 } }];

// Mismo contrato que la consulta vieja a pausados: { pausado: 0|1 }.
// Asi el IF que viene detras se trasplanta sin tocarlo.
const r = $json || {};
let c = r.body;
if (typeof c === 'string') { try { c = JSON.parse(c); } catch (e) {} }
const fila = Array.isArray(c) && c.length ? c[0] : null;
// Si no se puede leer, asumimos NO pausado y seguimos (igual que antes).
const activo = fila ? fila.bot_activo !== false : true;
return [{ json: { pausado: activo ? 0 : 1 } }];

// Mismo contrato que la consulta vieja a pausados: { pausado: 0|1 }.
// Asi el IF que viene detras se trasplanta sin tocarlo.
const r = $json || {};
let c = r.body;
if (typeof c === 'string') { try { c = JSON.parse(c); } catch (e) {} }
const fila = Array.isArray(c) && c.length ? c[0] : null;
// Si no se puede leer, asumimos NO pausado y seguimos (igual que antes).
const activo = fila ? fila.bot_activo !== false : true;
return [{ json: { pausado: activo ? 0 : 1 } }];

// Mismo contrato que la consulta vieja a pausados: { pausado: 0|1 }.
// Asi el IF que viene detras se trasplanta sin tocarlo.
const r = $json || {};
let c = r.body;
if (typeof c === 'string') { try { c = JSON.parse(c); } catch (e) {} }
const fila = Array.isArray(c) && c.length ? c[0] : null;
// Si no se puede leer, asumimos NO pausado y seguimos (igual que antes).
const activo = fila ? fila.bot_activo !== false : true;
return [{ json: { pausado: activo ? 0 : 1 } }];

// Contrato del punto único de salida.
const p = $('Preparar envío humano').first().json;
return [{ json: {
  accion: 'texto',
  cliente_id: $('Variables').first().json.numero_cliente,
  texto: p.texto,
  autor: 'bot',
} }];

const f = $('Procesar Foto').first().json;
return [{ json: {
  accion: 'imagen',
  cliente_id: $('Variables').first().json.numero_cliente,
  media_url: f.foto_url || f.media || null,
  texto: String(f.texto_final || '').replace(/\|\|\|/g, '\n'),
  autor: 'bot',
} }];

const d = $('Decidir ficha').first().json;
return [{ json: {
  accion: 'imagen',
  cliente_id: $('Variables').first().json.numero_cliente,
  media_url: d.imagen || d.media || null,
  texto: d.texto,
  autor: 'bot',
} }];

// Lo único que se le dice al cliente después de dar sus datos.
// Regla dura: silencio total salvo esto.
return [{ json: {
  accion: 'texto',
  cliente_id: $('Variables').first().json.numero_cliente,
  texto: '¡Gracias! 😊',
  autor: 'bot',
} }];

// Se funden en una sola llamada: marcar como leido Y mostrar "escribiendo".
// Solo se llega aqui si el bot va a responder (bot_activo = true), que es
// la regla: nunca mostrar el indicador si no vamos a contestar.
return [{ json: {
  accion: 'marcar_leido',
  wa_message_id: $('Variables').first().json.mensaje_id,
  typing: true,
} }];

const ev   = $('Normalizar evento').first().json;
const meta = $('MEDIA pedir URL a Graph').first().json;

const mime = String(meta.mime_type || ev.media_mime || '').split(';')[0].trim();
const EXT = {
  'audio/ogg': 'ogg', 'audio/mpeg': 'mp3', 'audio/mp4': 'm4a', 'audio/amr': 'amr',
  'image/jpeg': 'jpg', 'image/png': 'png', 'image/webp': 'webp',
  'video/mp4': 'mp4', 'video/3gpp': '3gp',
  'application/pdf': 'pdf',
};
const ext = EXT[mime] || 'bin';

// DURACION. Meta no la manda en el webhook y la regla de los 2 segundos
// la necesita, asi que se saca del propio fichero: en Ogg/Opus el granule
// de la ultima pagina son muestras a 48 kHz.
//
// OJO: este workflow va con binaryMode=separate, o sea que el binario NO
// viaja dentro de $binary.data.data (ahi solo queda una referencia corta,
// lo comprobamos: 13 caracteres). Hay que pedirle el buffer al helper.
// Si no se puede, Whisper devuelve tambien la duracion en verbose_json.
let duracion = null;
try {
  if (mime.startsWith('audio/ogg')) {
    let bin = null;
    try { bin = await this.helpers.getBinaryDataBuffer(0, 'data'); } catch (e) {}
    if (!bin) {
      const b = ($input.first().binary || {}).data;
      if (b && b.data && b.data.length > 100) bin = Buffer.from(b.data, 'base64');
    }
    if (bin) {
      for (let i = bin.length - 27; i >= 0; i--) {
        if (bin[i] === 0x4f && bin[i+1] === 0x67 && bin[i+2] === 0x67 && bin[i+3] === 0x53) {
          // Sin redondear: 1,6 s tiene que seguir siendo MENOR que 2.
          duracion = Number((Number(bin.readBigUInt64LE(i + 6)) / 48000).toFixed(2));
          break;
        }
      }
    }
  }
} catch (e) { /* no es critico, Whisper la trae */ }

// RUTA. En los documentos se cuelga el nombre real detras del media_id,
// con el mismo formato que usan los salientes ({sello}-{nombre}). Asi el
// inbox saca el nombre de la ruta con nombreDeRuta() y no hace falta una
// columna nueva en `adjuntos`. Un PDF entrante sin esto se enseñaba como
// "3949679035338900.pdf".
let ruta;
if (ev.tipo === 'document' && ev.nombre_fichero) {
  const seguro = String(ev.nombre_fichero)
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^A-Za-z0-9._-]+/g, '-')
    .replace(/-{2,}/g, '-')
    .replace(/^[-.]+/, '')
    .slice(0, 80);
  ruta = ev.cliente_id + '/' + ev.media_id + '-' + (seguro || 'documento.' + ext);
} else {
  ruta = ev.cliente_id + '/' + ev.media_id + '.' + ext;
}

return [{
  json: {
    cliente_id:    ev.cliente_id,
    wa_message_id: ev.wa_message_id,
    media_id:      ev.media_id,
    tipo:          ev.tipo,
    mime, ext, duracion,
    ruta,
    tamano: meta.file_size || null,
  },
  binary: $input.first().binary,
}];

const p = $('MEDIA preparar').first().json;

// Normalizamos las tres formas en que puede llegar la respuesta:
// cuerpo array, cuerpo cadena sin parsear, o ya partido en items.
let filas = ($json || {}).body;
if (filas === undefined) filas = $json;
if (typeof filas === 'string') { try { filas = JSON.parse(filas); } catch (e) {} }
if (!Array.isArray(filas)) filas = filas ? [filas] : [];
const fila = filas.find(f => f && f.id) || null;

if (!fila || !fila.id) {
  // Sin mensaje al que colgarse, la FK rechazaria el insert.
  return [{ json: { saltar: true, motivo: 'no se encontro el mensaje ' + p.wa_message_id } }];
}

// adjuntos.tipo solo admite image|audio|video|document|sticker.
const TIPOS = ['image','audio','video','document','sticker'];

return [{ json: {
  saltar: false,
  mensaje_id:   fila.id,
  tipo:         TIPOS.includes(p.tipo) ? p.tipo : 'document',
  storage_path: p.ruta,
  tamano:       p.tamano,
  // adjuntos.duracion es INT: se redondea para guardar, pero la regla
  // de los 2 s trabaja con el decimal que calculo MEDIA preparar.
  duracion:     p.duracion == null ? null : Math.round(p.duracion),
} }];

// Punto de reunion de todos los fallos de la cadena: Graph, la descarga,
// la subida al Storage o la bajada para transcribir. Emite el MISMO
// contrato que "TRANSCRIBIR leer resultado" para que "AUDIO decidir" no
// tenga que saber por donde se rompio.
const ev = $('Normalizar evento').first().json;
const e = $json || {};
const detalle = (e.error && e.error.message) || e.message ||
                JSON.stringify(e).slice(0, 160);

// La duracion puede haberse calculado antes de romperse: si murio en la
// subida, MEDIA preparar ya habia corrido. Si la tenemos, un audio de
// medio segundo sigue siendo de medio segundo: silencio, no aviso.
let duracion = null;
try { duracion = $('MEDIA preparar').first().json.duracion; } catch (err) {}

return [{ json: {
  ok: false,
  texto: null,
  duracion,
  motivo: 'fallo la cadena de media: ' + detalle,
  tipo: ev.tipo,
  ruta: null,
} }];

const r = $json || {};
const codigo = r.statusCode || 0;
let cuerpo = r.body;
if (typeof cuerpo === 'string') { try { cuerpo = JSON.parse(cuerpo); } catch (e) {} }

const p = $('MEDIA preparar').first().json;

let texto = null, motivo = null;

// La duracion de verbose_json manda sobre la del granule: la mide el
// propio Whisper sobre el audio ya decodificado.
let duracion = (cuerpo && typeof cuerpo.duration === 'number') ? cuerpo.duration : p.duracion;

if (codigo >= 200 && codigo < 300 && cuerpo && cuerpo.text) {
  texto = String(cuerpo.text).trim();

  // Con silencio o puro ruido Whisper casi nunca devuelve vacio: alucina
  // cosas como "Gracias por ver el video". Por eso no basta con mirar el
  // texto, hay que mirar su propia confianza. verbose_json trae
  // no_speech_prob por segmento: si TODOS los segmentos dicen que ahi no
  // hay voz, no hay voz, diga lo que diga el texto.
  const segs = Array.isArray(cuerpo.segments) ? cuerpo.segments : [];
  const sinVoz = segs.length > 0 &&
    segs.every(s => typeof s.no_speech_prob === 'number' && s.no_speech_prob > 0.6);

  if (texto.length < 2) { texto = null; motivo = 'audio sin habla'; }
  else if (sinVoz) {
    texto = null;
    motivo = 'Whisper no oye voz (no_speech_prob > 0.6 en todos los segmentos)';
  }
} else {
  motivo = 'Whisper devolvio ' + codigo + ': ' +
           JSON.stringify((cuerpo && cuerpo.error) || cuerpo).slice(0, 160);
}

return [{ json: { ok: !!texto, texto, duracion, motivo, tipo: p.tipo, ruta: p.ruta } }];

// REGLAS DEL AUDIO ENTRANTE
//
//   < 2 s ............... Maria calla. Suele ser el cliente pulsando sin
//                         querer. El audio se descarga, se guarda y se
//                         transcribe igual: en el inbox se ve. Ni alerta,
//                         ni pausa, ni cuenta como mensaje sin responder.
//   >= 2 s y sin texto .. Una sola frase pidiendo que lo repita, en tono
//                         humano, + aviso a Incidencias. No pausa.
//   >= 2 s y con texto .. El texto entra al bot como un mensaje normal.
//                         Maria responde al CONTENIDO y punto, sin avisos.
//
// UMBRAL. Empezo en 2 s y se subio a 2,5 el 22/08: un audio que WhatsApp
// pintaba como "0:02" medía 2,009 s y se colaba por 9 milisegundos.
// Whisper saco de el "Pero que..." y Maria contesto "Digame, que duda
// tiene?" a un pulsado sin querer. Por debajo no se puede bajar mucho:
// un "hola" real sale en 1,2 s y ese SI hay que contestarlo.
const UMBRAL = 2.5;

const ev = $('Normalizar evento').first().json;

let t = null;
try { t = $('TRANSCRIBIR leer resultado').first().json; } catch (e) {}
let fallo = null;
try { fallo = $('MEDIA fallo').first().json; } catch (e) {}

const base  = t || fallo || {};
const tipo  = base.tipo || ev.tipo;
const texto = base.ok ? base.texto : null;
const duracion = base.duracion == null ? null : Number(base.duracion);
const motivo = base.motivo || null;

let via;
if (tipo !== 'audio') {
  // Foto, video o documento: esta rama no opina, sigue el bot como siempre.
  via = 'normal';
} else if (duracion != null && duracion < UMBRAL) {
  // Corto: se ha guardado y transcrito, pero Maria no dice nada.
  via = 'corto';
} else if (texto) {
  via = 'normal';
} else {
  // >= 2 s (o duracion desconocida) y sin texto utilizable.
  via = 'ilegible';
}

return [{ json: {
  via, tipo, texto, duracion, motivo,
  cliente_id:    ev.cliente_id,
  wa_message_id: ev.wa_message_id,
} }];

// Dos decisiones distintas, que antes eran una:
//   callar  -> silenciada o bloqueada: ni mensaje al cliente ni aviso al
//             dueño. Silenciar significa exactamente eso.
//   pausado -> hay un humano al mando: el aviso SI se manda (le interesa
//             enterarse), pero el mensaje automatico al cliente no.
const r = $json || {};
let c = r.body;
if (typeof c === 'string') { try { c = JSON.parse(c); } catch (e) {} }
const fila = Array.isArray(c) && c.length ? c[0] : null;

// Si no se puede leer, asumimos NO pausado y NO callado, igual que en el
// resto del flujo: un aviso de mas cuesta menos que un cliente sin atender.
const activo = fila ? fila.bot_activo !== false : true;
const callar = !!(fila && (fila.silenciada === true || fila.bloqueada === true));

return [{ json: { pausado: activo ? 0 : 1, callar: callar ? 'si' : 'no' } }];

// Contrato del punto unico de salida (regla 2).
const d = $('AUDIO decidir').first().json;
return [{ json: {
  accion: 'texto',
  cliente_id: d.cliente_id,
  // Maria es HUMANA para el cliente. Ni una palabra que suene a maquina:
  // nada de "no puedo procesar audios". Una sola frase, y se calla.
  texto: 'Perdona, no me llegó bien tu audio, ¿me lo puedes repetir o escribir?',
  autor: 'bot',
} }];

// De que numero nuestro viene este mensaje.
//
// La llave es el phone_number_id que manda Meta en metadata. NO se
// deduce del texto ni del pais del cliente: es el unico dato fiable de
// quien recibio el mensaje.
const ev = $('Normalizar evento').first().json;
const r = $json || {};
let cuerpo = r.body;
if (typeof cuerpo === 'string') { try { cuerpo = JSON.parse(cuerpo); } catch (e) {} }
const fila = Array.isArray(cuerpo) && cuerpo.length ? cuerpo[0] : null;

return [{ json: Object.assign({}, ev, {
  canal_id:        fila ? fila.id : null,
  canal_nombre:    fila ? fila.nombre : null,
  canal_activo:    fila ? fila.activo !== false : false,
  canal_prompt:    fila ? (fila.prompt_url || null) : null,
  canal_hoja:      fila ? (fila.catalogo_hoja || null) : null,
  canal_ventana:   fila ? fila.ventana_horas : null,
  // Numero DESCONOCIDO: no esta dado de alta en `canales`. El mensaje
  // se guarda igual (regla 1) y se avisa. Nunca se pierde nada por no
  // tener una fila de configuracion.
  canal_desconocido: fila ? 'no' : 'si',
}) }];

// PROMPT COMUN + PROMPT DEL CANAL, en este orden y nunca al reves.
//
// El comun manda: dice quien es Maria, como habla y que no puede hacer.
// El del canal solo aporta DATOS de ese mercado (moneda, entrega,
// saludo). Va detras y etiquetado como datos, para que si alguien
// escribe una regla ahi por error, quede claro que no es su sitio.
const comun = String($('Leer Prompt').first().json.data || $('Leer Prompt').first().json || '');

let canal = '';
try {
  const r = $('Leer prompt del canal').first().json;
  const codigo = r.statusCode || 0;
  if (codigo >= 200 && codigo < 300) canal = String(r.body || '');
} catch (e) {}

// Un Doc de canal que crece es la senal de que se estan colando reglas
// donde solo deberian ir datos. 2000 caracteres es mucho para "moneda,
// entrega y saludo": si se pasa, se avisa en el log de la ejecucion.
const AVISO_LARGO = 2000;
const demasiado = canal.length > AVISO_LARGO;

const nombreCanal = $('Resolver canal').first().json.canal_nombre || 'sin canal';

const partes = [comun.trim()];
if (canal.trim()) {
  partes.push(
    '\n\n=== DATOS DE ESTE CANAL: ' + nombreCanal + ' ===',
    'Lo que sigue son DATOS del mercado en el que estas atendiendo ahora',
    '(pais, moneda, entrega, saludo). Si algo de aqui contradijera las',
    'reglas de arriba, mandan las de arriba.',
    '',
    canal.trim(),
  );
}

return [{ json: {
  data: partes.join('\n'),
  _canal: nombreCanal,
  _largo_comun: comun.length,
  _largo_canal: canal.length,
  _aviso: demasiado ? 'El prompt del canal pasa de ' + AVISO_LARGO + ' caracteres: probablemente lleva reglas que deberian estar en el comun.' : null,
} }];
